// Level 3 - "Who's that protein?": what we tell the player about each protein, and the rounds.
import { t } from '../i18n.js';
// The surface meshes (<id>.bin) are generated by tools/make-surface.mjs.

export const CATEGORIES = {
  defense: { color: '#ff6a6a' },
  structure: { color: '#ffb020' },
  communication: { color: '#7dff6a' },
  transport: { color: '#38e8ff' },
  enzyme: { color: '#ff3df2' },
  storage: { color: '#a58bff' },
  tool: { color: '#ffd166' },
};

export const POOL = {
  igg: {
    pdb: '1IGT', category: 'defense',
  },
  ferritin: {
    pdb: '1FHA', category: 'storage',
  },
  collagen: {
    pdb: '1BKV', category: 'structure',
  },
  serca: {
    pdb: '1SU4', category: 'transport',
  },
  amylase: {
    pdb: '1PPI', category: 'enzyme',
  },
  hemoglobin: {
    pdb: '4HHB', category: 'transport',
  },
  gfp: {
    short: 'GFP', pdb: '1EMA', category: 'tool',
  },
  insulin: {
    pdb: '3I40', category: 'communication',
  },
  lysozyme: {
    pdb: '2LZT', category: 'defense',
  },
  myoglobin: {
    pdb: '1MBN', category: 'storage',
  },
  ubiquitin: {
    pdb: '1UBQ', category: 'tool',
  },
  crambin: {
    pdb: '1CRN', category: 'structure',
  },
};

// Texts live in src/lang/*.js (cat.<id>, pool.<id>.name / clue / fact) and are read through getters.
for (const [id, c] of Object.entries(CATEGORIES)) Object.defineProperty(c, 'label', { get: () => t('cat.' + id), enumerable: true });
for (const [id, p] of Object.entries(POOL)) {
  for (const f of ['name', 'clue', 'fact']) Object.defineProperty(p, f, { get: () => t(`pool.${id}.${f}`), enumerable: true });
}

// Rounds: the target and the other choices. "twist": how the choices are turned at the start
// (none = same view as the shadow, roll = turned in the plane, free = any orientation).
export const ROUNDS = [
  { target: 'igg', others: ['ferritin', 'collagen', 'gfp'], twist: 'none' },
  { target: 'ferritin', others: ['serca', 'collagen', 'myoglobin'], twist: 'none' },
  { target: 'collagen', others: ['igg', 'hemoglobin', 'amylase'], twist: 'none' },
  { target: 'serca', others: ['amylase', 'gfp', 'hemoglobin'], twist: 'roll' },
  { target: 'amylase', others: ['lysozyme', 'myoglobin', 'gfp'], twist: 'roll' },
  { target: 'hemoglobin', others: ['myoglobin', 'ferritin', 'igg'], twist: 'roll' },
  { target: 'gfp', others: ['lysozyme', 'ubiquitin', 'myoglobin'], twist: 'free' },
  { target: 'insulin', others: ['crambin', 'ubiquitin', 'lysozyme'], twist: 'free' },
];
